-- Cerebro de empresa vigente de DALFAN, exportado de la base real el 2026-10-09 17:08 UTC
-- Fuente: companies.company_sales_brain de la empresa DALFAN de emiliofanjul1@hotmail.com (company_brain_versions está vacía para DALFAN).
-- Filas: 1 (cerebro vigente, sin historial). Sin ids de empresa ni de usuarios.
-- Se asigna a la empresa llamada 'Empresa Prueba'; cambia el nombre en el WHERE si hace falta.
UPDATE public.companies SET company_sales_brain = E'{"RESTRICCIONES": "Nunca prometer una fecha de entrega sin confirmar inventario y ruta.\\n\\nNunca asegurar que un pedido llegará completo sin revisar existencias.\\n\\nNunca inventar disponibilidad de producto.\\n\\nNunca ofrecer precios, promociones o descuentos no autorizados.\\n\\nNunca prometer crédito, más días de crédito o ampliaciones sin autorización.\\n\\nNunca prometer devoluciones, cambios o bonificaciones sin aprobación.\\n\\nNunca garantizar que un producto nuevo se venderá.\\n\\nNunca decir que un producto “se vende solo”.\\n\\nNunca afirmar que un producto es mejor que otro sin argumentos comprobables.\\n\\nNunca desacreditar a la competencia.\\n\\nNunca recomendar un lubricante sin comprobar la aplicación.\\n\\nNunca decir que dos productos son equivalentes sin revisar viscosidades y especificaciones.\\n\\nNunca inventar homologaciones, aprobaciones o certificaciones.\\n\\nNunca prometer que un producto no causará ninguna falla.\\n\\nNunca ampliar intervalos de cambio solamente para cerrar una venta.\\n\\nNunca ocultar condiciones de precio, pronto pago, promoción o pedido mínimo.\\n\\nNunca presionar al cliente para comprar inventario que claramente no necesita.\\n\\nNunca culpar frente al cliente al almacén, reparto, crédito o administración.\\n\\nNunca compartir precios o condiciones confidenciales de otros clientes.\\n\\nCuando el vendedor no conozca una respuesta, debe decir que la confirmará y dar seguimiento.", "CLIENTE_TIPICO": "Tipos de clientes que atendemos\\n\\nRefaccionarias.\\n\\nTalleres mecánicos.\\n\\nTalleres de motocicletas.\\n\\nTiendas de accesorios y refacciones para motocicletas.\\n\\nGasolineras.\\n\\nLubricentros y negocios de cambio de aceite.\\n\\nFerreterías que venden ciertas especialidades.\\n\\nEmpresas de transporte.\\n\\nPropietarios de flotillas.\\n\\nEmpresas con vehículos de reparto.\\n\\nIndustrias y empresas con consumo propio.\\n\\nNegocios que revenden lubricantes al consumidor final.\\n\\nClientes mayoristas y subdistribuidores regionales.\\n\\n⸻\\n\\nCómo es tu cliente típico\\n\\nNo existe un solo perfil de cliente, pero la mayoría comparte las siguientes características:\\n\\nEs una persona práctica y orientada a la operación diaria.\\n\\nTiene poco tiempo para escuchar una presentación larga.\\n\\nValora que el vendedor conozca su negocio, sus productos y lo que normalmente compra.\\n\\nSe preocupa mucho por el precio, pero no decide exclusivamente por el precio.\\n\\nLe importa tener producto disponible cuando lo necesita.\\n\\nLe preocupa que una mercancía nueva se quede detenida y no se venda.\\n\\nPrefiere comprar productos que ya conoce o que sus propios clientes solicitan.\\n\\nConfía más en recomendaciones concretas que en discursos técnicos demasiado largos.\\n\\nValora que el vendedor cumpla lo que acuerda.\\n\\nLe molesta que le cambien precios, promociones, fechas de entrega o condiciones después de hacer el pedido.\\n\\nPuede tener varios proveedores y repartir sus compras entre ellos.\\n\\nCompara precios, promociones, crédito, disponibilidad, servicio y rapidez de entrega.\\n\\nEn muchos casos, toma decisiones pequeñas rápidamente, pero necesita más argumentos para cambiar de marca, incorporar una nueva línea o hacer una compra grande.\\n\\nGeneralmente busca proteger su flujo de efectivo y evita comprar inventario que no sabe cuánto tardará en vender.\\n\\nLe interesa obtener margen, rotación y facilidad de reventa.\\n\\nNo siempre conoce todas las especificaciones técnicas, por lo que necesita recomendaciones claras y responsables.\\n\\nPuede sentirse incómodo si el vendedor intenta demostrar que sabe más que él o desacredita los productos que actualmente maneja.\\n\\nResponde mejor cuando el vendedor escucha primero, identifica una necesidad y después hace una recomendación específica.\\n\\nValora la relación personal y la continuidad. Un vendedor confiable puede convertirse en una parte importante de su decisión de compra.\\n\\n⸻\\n\\nQué le importa al cliente\\n\\nQue el producto tenga demanda.\\n\\nQue pueda ganar dinero al revenderlo.\\n\\nQue el precio sea competitivo.\\n\\nQue exista una promoción clara.\\n\\nQue el pedido llegue completo.\\n\\nQue llegue en la fecha acordada.\\n\\nQue no le vendan una aplicación incorrecta.\\n\\nQue el producto tenga respaldo.\\n\\nQue haya continuidad en el abastecimiento.\\n\\nQue el vendedor responda cuando existe un problema.\\n\\nQue las condiciones de crédito sean claras.\\n\\nQue no se le obligue a comprar más producto del que puede desplazar.\\n\\nQue las presentaciones se adapten al consumo de su negocio.\\n\\nQue el producto funcione correctamente.\\n\\nQue la marca sea reconocida o que tenga argumentos suficientes para recomendarla.\\n\\nQue el proveedor facilite la operación y no genere problemas adicionales.\\n\\n⸻\\n\\nCómo decide\\n\\nEn una venta recurrente, el cliente normalmente decide combinando estos factores:\\n\\nNecesidad inmediata de inventario.\\n\\nRotación histórica del producto.\\n\\nPrecio final.\\n\\nPromoción disponible.\\n\\nDescuento por pronto pago.\\n\\nCrédito disponible.\\n\\nConfianza en el vendedor.\\n\\nConfianza en la marca.\\n\\nDisponibilidad para entrega.\\n\\nComparación contra otro proveedor.\\n\\nCantidad mínima necesaria.\\n\\nDinero disponible en ese momento.\\n\\nMargen que espera obtener.\\n\\nSolicitud específica de sus propios clientes.\\n\\nExperiencias previas con el producto.\\n\\nRiesgo percibido de que el producto no se venda.\\n\\nPara una línea nueva, la decisión requiere disminuir el riesgo. El cliente suele necesitar entender quién va a comprar el producto, cuánto margen puede obtener, qué aplicación tiene, por qué debería probarlo y con qué cantidad pequeña puede comenzar.\\n\\nPara una flotilla o empresa de autoconsumo, la decisión es más técnica. Se consideran especificaciones, homologaciones, compatibilidad, desempeño, continuidad de suministro, precio total, condiciones de pago y riesgo operativo.", "TONO_DETECTADO": "Familiar — relación de negocio continua. La relación con el cliente es cercana, práctica y directa.  El vendedor debe hablar de manera natural, sin sonar excesivamente formal, corporativo o ensayado.  Debe escuchar antes de ofrecer.  Debe hacer preguntas breves y relevantes.  Debe demostrar conocimiento sin hacer sentir al cliente que sabe menos.  Debe ser seguro, pero no arrogante.  Debe ser persistente, pero no agresivo.  No debe hablar mal de la competencia. Puede comparar productos, precios o servicios usando hechos concretos.  Debe cerrar con propuestas específicas y evitar terminar siempre con frases como “ahí me avisas”.  Ejemplos del tono correcto:  “¿Qué es lo que más se te está moviendo?”  “¿Qué producto estás comprando con otro proveedor?”  “¿Qué te preocupa más: el precio, la rotación o que no conozcan la marca?”  “Para que no te cargues de inventario, podemos empezar con esta cantidad.”  “Déjame confirmar la existencia y la fecha antes de comprometértela.”  “Con la promoción y el pronto pago, tu costo final queda en…”", "CONTEXTO_DE_VENTA": "Cómo es una venta típica\\n\\nEscenario principal: preventa en ruta\\n\\nLa mayoría de las ventas se realizan mediante visitas presenciales de un vendedor a los negocios de su ruta.\\n\\nEl vendedor no lleva toda la mercancía en el vehículo para venderla en ese momento. Levanta el pedido y posteriormente DALFAN prepara y entrega la mercancía desde el almacén correspondiente.\\n\\nEl vendedor visita refaccionarias, talleres, gasolineras y otros negocios de la zona.\\n\\nLa interacción normalmente ocurre dentro del establecimiento, en el mostrador, oficina, almacén o zona de trabajo.\\n\\nEl ambiente puede ser ruidoso, con clientes entrando, llamadas, vehículos, mecánicos trabajando y otras interrupciones.\\n\\nEl cliente frecuentemente está atendiendo su negocio mientras habla con el vendedor.\\n\\nEl tiempo disponible puede ser breve. Una visita sencilla puede durar entre cinco y quince minutos. Una conversación sobre una nueva línea, una promoción importante o una negociación puede durar más.\\n\\nLa venta muchas veces inicia revisando qué productos necesita el cliente, qué se le está terminando, qué se vendió desde la visita anterior o qué promoción se encuentra vigente.\\n\\nEl vendedor debe observar el negocio, recordar compras anteriores y hacer preguntas breves antes de recomendar.\\n\\nUna venta típica puede incluir:\\n\\nSaludo y conversación breve.\\n\\nRevisión de necesidades actuales.\\n\\nConsulta sobre inventario o rotación.\\n\\nPresentación de productos, promociones o novedades relevantes.\\n\\nExplicación del precio de lista, promoción y beneficio por pronto pago cuando corresponda.\\n\\nRespuesta a dudas u objeciones.\\n\\nPropuesta de cantidades concretas.\\n\\nCierre del pedido.\\n\\nRevisión de productos complementarios.\\n\\nConfirmación de cantidades, presentaciones, precios y condiciones.\\n\\nSeguimiento posterior sobre entrega, faltantes o pagos.\\n\\n⸻\\n\\nVenta recurrente\\n\\nEn una venta recurrente, el cliente ya conoce al vendedor, a DALFAN y a varias de las marcas.\\n\\nEl principal riesgo es que la visita se convierta únicamente en “¿qué te hace falta?”, sin realizar descubrimiento, sin presentar productos adicionales y sin desarrollar la cuenta.\\n\\nCloser debe entrenar al vendedor para que no se limite a tomar pedidos.\\n\\nDebe ayudarlo a:\\n\\nDetectar categorías que el cliente todavía no compra.\\n\\nIdentificar productos que están perdiendo rotación.\\n\\nRecomendar sustitutos cuando no existe inventario.\\n\\nPresentar promociones relevantes.\\n\\nIncrementar el número de categorías por cliente.\\n\\nRecuperar productos que el cliente dejó de comprar.\\n\\nEntender qué compra con otros proveedores y por qué.\\n\\nCerrar cantidades específicas, no solamente dejar una cotización.\\n\\n⸻\\n\\nVenta de una línea o producto nuevo\\n\\nEl cliente puede mostrarse interesado, pero sentir que probar un producto nuevo representa un riesgo.\\n\\nEl vendedor debe evitar presentar demasiados productos a la vez.\\n\\nDebe elegir una oportunidad concreta y explicar:\\n\\nPara qué tipo de consumidor o vehículo sirve.\\n\\nQué problema resuelve.\\n\\nQué ventaja comercial tiene.\\n\\nQué margen o rotación podría generar.\\n\\nQué producto actual puede complementar o sustituir.\\n\\nCon qué cantidad razonable puede iniciar.\\n\\nCómo puede recomendarlo al consumidor final.\\n\\nLa meta inicial no siempre es desplazar de inmediato a toda la competencia. Puede ser conseguir una prueba controlada, medir la respuesta y después ampliar el pedido.\\n\\n⸻\\n\\nVenta a flotillas, transporte o industria\\n\\nEstas ventas son más consultivas y pueden requerir varias conversaciones.\\n\\nLa interacción puede ser con el dueño, encargado de mantenimiento, jefe de taller, gerente de compras, administrador o responsable de operaciones.\\n\\nAntes de recomendar un producto, se necesita conocer:\\n\\nTipo de unidades o maquinaria.\\n\\nMarca, modelo y año.\\n\\nMotor, transmisión o componente.\\n\\nProducto que utilizan actualmente.\\n\\nViscosidad.\\n\\nEspecificación o aprobación requerida.\\n\\nIntervalo de cambio.\\n\\nConsumo mensual.\\n\\nPresentación utilizada.\\n\\nProblemas actuales.\\n\\nCondiciones de almacenamiento.\\n\\nProveedor actual.\\n\\nPrecio y condiciones de pago.\\n\\nUna venta industrial o de flotilla puede incluir una revisión técnica, homologación de productos, cotización, prueba inicial y seguimiento.\\n\\nEl vendedor nunca debe recomendar un producto basándose únicamente en que “es parecido” o “es mejor”. Debe comprobar la aplicación y las especificaciones.", "OBJECIONES_REALES": "Encontré un proveedor que me da un precio ligeramente más bajo; No completo el pedido mínimo esta quincena, ¿me puedes vender menos?; Necesito seguridad de que el pedido llegará el martes, no el miércoles; Mis clientes dicen que el producto X de la competencia está funcionando mejor.; Todavía tengo producto y no quiero comprar más inventario.; Esa marca no me la piden mis clientes.; No conozco el producto y no sé si se va a vender.; Mi proveedor actual me da más días de crédito.; No quiero meter otra marca porque ya manejo demasiadas.; Mis clientes prefieren o me piden la marca de la competencia.; No quiero comprar mercancía solamente para alcanzar el volumen de la promoción.; Déjame revisar con mi socio.; Déjame pensarlo.; Lo tengo que consultar con el dueño.; Compras tiene que autorizarlo.; Mándame la cotización y después te aviso.; Voy a comparar precios primero.; La próxima visita te confirmo.; Se terminó la temporada de mayor consumo.; Está muy baja la temporada.; Con ese precio no puedo competir.; Solo necesito una o dos piezas.", "PRODUCTOS_ACTIVOS": "DALFAN es una empresa distribuidora de lubricantes, anticongelantes, grasas, aditivos y otras especialidades automotrices e industriales.\\n\\nNuestro equipo comercial ofrece principalmente productos de las marcas Repsol, Bardahl y Mexlub. Atendemos desde pequeños talleres y refaccionarias hasta flotillas, transportistas, industrias, gasolineras y empresas con consumo propio de lubricantes.\\n\\nLas principales categorías que vendemos son:\\n\\nAceites para motores a gasolina.\\n\\nAceites para motores diésel.\\n\\nLubricantes para motocicletas.\\n\\nAceites para transmisiones manuales y automáticas.\\n\\nAceites para diferenciales y engranajes.\\n\\nFluidos ATF y otros fluidos para transmisión.\\n\\nAnticongelantes y refrigerantes.\\n\\nGrasas automotrices e industriales.\\n\\nLíquidos de frenos.\\n\\nAditivos para aceite.\\n\\nAditivos para combustible.\\n\\nLimpiadores de inyectores y del sistema de combustible.\\n\\nProductos aflojatodo y lubricantes multiusos.\\n\\nEspecialidades para talleres mecánicos.\\n\\nProductos para equipo pesado, tractocamiones y flotillas.\\n\\nLubricantes en presentaciones de litro, galón, cubeta, tambor y, cuando el proyecto lo requiere, volúmenes industriales.\\n\\nAdemás del producto, ofrecemos disponibilidad regional, entrega mediante rutas de reparto, asesoría para seleccionar la aplicación correcta, seguimiento comercial, promociones, alternativas entre marcas y presentaciones, y condiciones de crédito para clientes autorizados.\\n\\nNo vendemos solamente “aceite”. Vendemos una combinación de producto correcto, disponibilidad, abastecimiento, atención, respaldo y facilidad para que el cliente pueda seguir operando o revendiendo sin quedarse sin mercancía.\\n\\n⸻\\n\\nMarcas y posicionamiento general\\n\\nRepsol\\n\\nMarca internacional con una imagen tecnológica, moderna y de alto desempeño.\\n\\nEs especialmente relevante en lubricantes para automóviles, motocicletas, transporte pesado e industria.\\n\\nEntre sus fortalezas comerciales se encuentran su experiencia internacional, su presencia en competencias de motor, su tecnología, sus especificaciones y su capacidad para atender aplicaciones modernas.\\n\\nEn motocicletas, la relación histórica de Repsol con el motociclismo es una herramienta de reconocimiento, aunque el vendedor no debe depender únicamente de este argumento.\\n\\nEn transporte pesado, contamos con alternativas como lubricantes API CK-4 para motores diésel modernos, sujetos siempre a comprobar la especificación requerida por el fabricante.\\n\\nBardahl\\n\\nMarca ampliamente reconocida en México, con una presencia fuerte en talleres, refaccionarias, aditivos, anticongelantes, lubricantes y especialidades.\\n\\nSu reconocimiento ayuda a generar confianza entre clientes que ya conocen la marca y entre consumidores finales que la solicitan directamente.\\n\\nTiene un portafolio amplio que permite complementar el pedido del cliente y aumentar el número de categorías que compra.\\n\\nMexlub\\n\\nMarca con alternativas competitivas en lubricantes automotrices y para equipo pesado.\\n\\nPuede ser especialmente relevante cuando el cliente busca una buena relación entre precio, desempeño y disponibilidad.\\n\\nEs una herramienta para competir en segmentos sensibles al precio, sin ofrecer productos incorrectos o reducir la conversación únicamente al costo.", "ARGUMENTOS_DE_VALOR": "Ofrecemos la mejor relación precio-calidad del mercado para que maximices tu margen; Somos tu socio de confianza con entregas puntuales y consistentes cada dos semanas; Nuestro amplio catálogo te permite surtirte de todo lo que necesitas en un solo lugar, simplificando tu operación.; DALFAN distribuye marcas reconocidas como Repsol, Bardahl y Mexlub.; Contamos con un portafolio amplio que permite al cliente comprar varias categorías con un mismo proveedor.; Podemos proponer cantidades razonables para probar un producto nuevo sin cargar al cliente de inventario.; Ayudamos al cliente a identificar productos complementarios y oportunidades para aumentar sus ventas.; Para flotillas e industrias, revisamos la viscosidad, especificación y aplicación antes de recomendar un cambio.; Buscamos una relación de largo plazo, no solamente cerrar una venta aislada.", "Objetivo principal del vendedor": "Objetivo principal del vendedor\\n\\nDesarrollar cada cuenta de forma rentable, aumentando las ventas, la frecuencia de compra y el número de categorías que compra el cliente, sin afectar su rotación, crédito o confianza."}'::jsonb, onboarding_completed = true, brain_updated_at = now() WHERE name = 'Empresa Prueba';
